UPDATE [${dbxschemaname}].[configurations] SET config_value= '{"ProductGroup":[{"productName":"First Time Buyer","productRef":"FIRST.TIME.BUYER","productDescription":{"notes":"Flexibility to make overpayments.|+|Choose the length of your term. You can take up to 30 years so that your monthly payments suit your needs."},"imageDetails":[{"imageUrl":"money_bag.png","imageType":"Icon"}]},{"productName":"Remortgage","productRef":"REMORTGAGE","productDescription":{"notes":"Apply for a remortgage loan and get a better interest rate.|+|Switch your mortgage loan and choose to apply for additional loan amount.|+|Avail zero processing fees on your remortgage loan.|+|Enjoy flexible monthly repayment options with a tenure of up to 360 months."},"imageDetails":[{"imageUrl":"money_bag.png","imageType":"Icon"}]}],"ProductDetail":[{"ProductName":"First Time Buyer","productRef":"FIRST.TIME.BUYER","ProductDescription":"FirstTimeBuyer","purposeName":"First time buyer","ProductDetailedDescription":"Stepping onto mortgage ladder, Find out how to buy a home and take out a mortgage.","desc":"Deposit: We usually ask for 10% of the amount you want to borrow as a deposit.","ProductNotes":"Flexibility to make overpayments.|+|Choose the length of your term. You can take up to 30 years so that your monthly payments suit your needs.","imageDetails":[{"imageUrl":"landingpage_3_mortgageImg1.png","imageType":"Icon"}],"ProductTermsAndConditions":"1 Estimate obtained based on the information provided by the user. It does not constitute an offer for the application for a mortgage loan.<br>2 The application, granting and amount of the mortgage Loan will be subject to subsequent approval by our risks department.<br>3 Provided that you fulfil all our eligibilty requirements for a mortgage Loan.<br>4 Actual loan eligible amount depends on various factors such as credit history, prevailing interest rates and bank''s credit policy."},{"ProductName":"Remortgage","productRef":"REMORTGAGE","ProductDescription":"Remortgage","purposeName":"Remortgage","ProductDetailedDescription":"Transfer your existing mortgage loan held with another lender to us.","desc":"Get a remortgage loan worth up to 90% of your current property value.","ProductNotes":"Apply for a remortgage loan and get a better interest rate.|+|Switch your mortgage loan and choose to apply for additional loan amount.|+|Avail zero processing fees on your remortgage loan.|+|Enjoy flexible monthly repayment options with a tenure of up to 360 months.","imageDetails":[{"imageUrl":"landingpage_3_mortgageImg1.png","imageType":"Icon"}],"ProductTermsAndConditions":"1 Estimate obtained based on the information provided by the user. It does not constitute an offer for the application for a mortgage loan.<br>2 The application, granting and amount of the mortgage Loan will be subject to subsequent approval by our risks department.<br>3 Provided that you fulfil all our eligibilty requirements for a mortgage Loan.<br>4 Actual loan eligible amount depends on various factors such as credit history, prevailing interest rates and bank''s credit policy."}]}' WHERE (configuration_id = '170');
UPDATE [${dbxschemaname}].[configurations] SET config_value = '&emsp; 1.Proof of Identity\r\n&emsp;&emsp; a.Tax ID(mandatory)\r\n&emsp;&emsp; b.The ID which is entered under ID section to be pre populated\r\n(Any one document from below is Mandatory)\r\n&emsp;&emsp;&emsp;&emsp;  i. Driving License\r\n&emsp;&emsp;&emsp; &emsp; ii.Passport\r\n&emsp;&emsp;&emsp;&emsp;iii.Employee ID\r\n&emsp;&emsp;&emsp;&emsp; iv.Photo ID card issued by Local Government  <br>\r\n&emsp;2.Proof of Address : (Any one document from below is Mandatory)   \r\n&emsp;&emsp; a.Driving License    \r\n&emsp;&emsp; b.Passport    \r\n&emsp;&emsp; c.Utility Bills    \r\n&emsp;&emsp; d.Employer/HR letter   \r\n&emsp;&emsp; e.House Rent Contract <br>\r\n&emsp; 3.Proof of Income :    \r\n&emsp;&emsp;  a.For Status (Employment Status) - Salaried (Full Time Employee, Part Time Employee, Contract Employee, Casual Employee)    \r\n&emsp;&emsp;  &emsp;&emsp;     i.Pay-slips(mandatory) \r\n&emsp;&emsp;&emsp;    &emsp;  ii.Salary Account statement ( optional)    \r\n&emsp;&emsp; b.For Status(Employment Status) - Non-Salaried (Self-Employed, Retired,\r\n&emsp;&emsp;&emsp;Unemployed, Trainee)    \r\n&emsp;&emsp;&emsp;  &emsp;   i.Tax Return Statements(mandatory) \r\n&emsp;&emsp;&emsp;&emsp;   ii.Account Statements ( optional) <br>\r\n&emsp; 4.Product Document: First Time Buyer : (Add below documents if available)  \r\n&emsp;&emsp;  a.Initial/Advance Payment Receipt    \r\n&emsp;&emsp;  b.Sale Agreement    \r\n&emsp;&emsp;  c.Additional Mortgage Document <br>\r\n&emsp; 5.Property Document : (Add below documents if available)\r\n&emsp;&emsp;    a.Sale Deed    \r\n&emsp;&emsp;    b.Parent Document    \r\n&emsp;&emsp;    c.Plan Approval/Layout Approval \r\n&emsp;&emsp;    d.Property Tax Receipt    \r\n&emsp;&emsp;   e.Electricity, Water, and Drainage Certificate/Receipt' WHERE (configuration_id = '254');
